CREATE TABLE public.assessment_batteries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),payload jsonb NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','in_review','approved','rejected')),analysis_status text NOT NULL DEFAULT 'draft',created_by uuid DEFAULT auth.uid(),approved_by uuid,approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE ON public.assessment_batteries TO authenticated; GRANT ALL ON public.assessment_batteries TO service_role;ALTER TABLE public.assessment_batteries ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.assessment_access(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),battery_id uuid NOT NULL REFERENCES public.assessment_batteries(id),user_id uuid NOT NULL,permission text NOT NULL CHECK(permission IN ('sme','rater','fairness')),source_id text,UNIQUE(battery_id,user_id,permission));GRANT SELECT,INSERT,DELETE ON public.assessment_access TO authenticated;GRANT ALL ON public.assessment_access TO service_role;ALTER TABLE public.assessment_access ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.assessment_permission(bid uuid,p text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM assessment_access WHERE battery_id=bid AND user_id=auth.uid() AND permission=p) $$;REVOKE ALL ON FUNCTION public.assessment_permission(uuid,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.assessment_permission(uuid,text) TO authenticated,service_role;
CREATE POLICY access_read ON public.assessment_access FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.can_edit_workspace());CREATE POLICY access_assign ON public.assessment_access FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));CREATE POLICY access_remove ON public.assessment_access FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY battery_read ON public.assessment_batteries FOR SELECT TO authenticated USING(public.can_edit_workspace() OR public.has_role(auth.uid(),'hr_reviewer') OR EXISTS(SELECT 1 FROM assessment_access a WHERE a.battery_id=assessment_batteries.id AND a.user_id=auth.uid()));CREATE POLICY battery_create ON public.assessment_batteries FOR INSERT TO authenticated WITH CHECK(public.can_edit_workspace());CREATE POLICY battery_update ON public.assessment_batteries FOR UPDATE TO authenticated USING(public.can_edit_workspace() OR public.has_role(auth.uid(),'hr_reviewer') OR public.assessment_permission(id,'sme'));
CREATE TABLE public.assessment_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),battery_id uuid NOT NULL REFERENCES public.assessment_batteries(id),name text NOT NULL,token_hash text UNIQUE,expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days',revoked boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'invited' CHECK(status IN ('invited','in_progress','submitted','scored')),answers jsonb NOT NULL DEFAULT '{}',scores jsonb NOT NULL DEFAULT '{}',raters jsonb NOT NULL DEFAULT '[]',reconciliations jsonb NOT NULL DEFAULT '{}',section_deadlines jsonb NOT NULL DEFAULT '{}',current_section text,extra_minutes integer NOT NULL DEFAULT 0 CHECK(extra_minutes BETWEEN 0 AND 240),accommodation_request text NOT NULL DEFAULT '',alternate_format text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),submitted_at timestamptz);GRANT SELECT,INSERT,UPDATE ON public.assessment_attempts TO authenticated;GRANT ALL ON public.assessment_attempts TO service_role;ALTER TABLE public.assessment_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY attempt_read ON public.assessment_attempts FOR SELECT TO authenticated USING(public.can_edit_workspace() OR public.has_role(auth.uid(),'hr_reviewer') OR public.assessment_permission(battery_id,'rater'));CREATE POLICY attempt_insert ON public.assessment_attempts FOR INSERT TO authenticated WITH CHECK(public.can_edit_workspace());CREATE POLICY attempt_update ON public.assessment_attempts FOR UPDATE TO authenticated USING(public.can_edit_workspace() OR public.assessment_permission(battery_id,'rater'));
CREATE TABLE public.assessment_demographics(attempt_id uuid PRIMARY KEY REFERENCES public.assessment_attempts(id),group_label text NOT NULL DEFAULT '');GRANT SELECT ON public.assessment_demographics TO authenticated;GRANT ALL ON public.assessment_demographics TO service_role;ALTER TABLE public.assessment_demographics ENABLE ROW LEVEL SECURITY;CREATE POLICY demographic_review ON public.assessment_demographics FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'hr_reviewer') OR public.assessment_permission((SELECT battery_id FROM assessment_attempts WHERE id=attempt_id),'fairness'));
CREATE INDEX ON public.assessment_access(battery_id,user_id);CREATE INDEX ON public.assessment_attempts(battery_id);